insert into org.dominio (circulo, nome, descricao) select circulo, nome, descricao from jsonb_to_recordset($j$[{"circulo": 1, "nome": "Fundamento", "descricao": "Dizer quem somos e transformar isso em regra aplicável."}, {"circulo": 1, "nome": "Marca", "descricao": "Criar e proteger as marcas do Ecossistema e das empresas."}, {"circulo": 1, "nome": "Posicionamento", "descricao": "Definir a promessa e as mensagens para cada público."}, {"circulo": 1, "nome": "Avaliação", "descricao": "Conferir se os padrões funcionam e decidir o que rever."}, {"circulo": 2, "nome": "Direção e recursos", "descricao": "Escolher onde atuar, alocar os recursos e fixar os alvos."}, {"circulo": 2, "nome": "Apostas e empresas", "descricao": "Decidir o que entra, o que avança e o que sai do portfólio."}, {"circulo": 2, "nome": "Acompanhamento", "descricao": "Conferir se a estratégia é executada e se continua certa."}, {"circulo": 3, "nome": "Mercado e decisão", "descricao": "Saber antes: ler o mercado e responder a quem decide."}, {"circulo": 3, "nome": "Dados, indicadores e conhecimento", "descricao": "Saber melhor: dado confiável, medida única e base curada."}, {"circulo": 3, "nome": "Método e oferta", "descricao": "Transformar o que se sabe em método e em oferta."}, {"circulo": 3, "nome": "Aprendizado", "descricao": "Fechar o ciclo: da lição à melhoria conferida."}, {"circulo": 4, "nome": "Demanda", "descricao": "Planejar e executar a geração de demanda e entregar a Negócios oportunidades qualificadas."}, {"circulo": 4, "nome": "Clientes", "descricao": "Desenhar a experiência do cliente e cuidar do sucesso de cada cliente depois da venda."}, {"circulo": 4, "nome": "Parcerias e instituições", "descricao": "Formar e cuidar de parcerias e relações institucionais e decidir o uso da marca por terceiros."}, {"circulo": 4, "nome": "Comunicação e reputação", "descricao": "Comunicar para fora e vigiar como os públicos percebem as marcas."}, {"circulo": 5, "nome": "Preço e plano comercial", "descricao": "Manter a tabela de preços e a política comercial, planejar as vendas e prever a receita."}, {"circulo": 5, "nome": "Venda", "descricao": "Aceitar a oportunidade, fazer a proposta, negociar e fechar o contrato, e disputar licitações."}, {"circulo": 5, "nome": "Contas e contratos", "descricao": "Renovar, ampliar, aditar e encerrar os contratos dos clientes."}, {"circulo": 5, "nome": "Venda conjunta", "descricao": "Vender com parceiros e em oferta conjunta entre as empresas do Ecossistema."}, {"circulo": 6, "nome": "Projetos e implantação", "descricao": "Carteira de projetos, implantação de clientes, lançamento de ofertas e saída de ofertas e empresas: a Integração como escritório de projetos."}, {"circulo": 6, "nome": "Capacidades e agentes", "descricao": "Catálogo de capacidades, pedidos de serviço entre empresas e círculos, e agentes e automações do desenho ao uso."}, {"circulo": 6, "nome": "Tecnologia e jornadas", "descricao": "Operação da tecnologia e melhoria das jornadas ponta a ponta."}, {"circulo": 7, "nome": "Capacidade e entrega", "descricao": "Capacidade planejada, entrega recorrente a cada cliente e encerramento das entregas."}, {"circulo": 7, "nome": "Atendimento e qualidade", "descricao": "Atendimento de pedidos e problemas, tratamento de reclamações, padrões, níveis de serviço e ação corretiva."}, {"circulo": 7, "nome": "Produto físico", "descricao": "Cadeia de suprimentos e pós-venda, só onde a oferta tem produto físico."}, {"circulo": 8, "nome": "Planejamento e controle", "descricao": "Orçamento aprovado desdobrado e controlado e ritual de acompanhamento dos alvos."}, {"circulo": 8, "nome": "Finanças", "descricao": "Faturamento e cobrança, compras e pagamentos, caixa, contas, impostos, prestação de contas e rateio."}, {"circulo": 8, "nome": "Pessoas e cultura", "descricao": "Provimento, integração à cultura, avaliação, desenvolvimento, folha, rituais, reconhecimento e comunicação interna."}, {"circulo": 8, "nome": "Ativos e administração", "descricao": "Ativos, espaços e serviços administrativos."}, {"circulo": 9, "nome": "Regras e decisões", "descricao": "Regras, políticas e alçadas de pessoas e agentes e a secretaria das decisões dos sócios."}, {"circulo": 9, "nome": "Riscos e conformidade", "descricao": "Riscos, controles internos, conformidade e obrigações legais em dia."}, {"circulo": 9, "nome": "Contratos e auditoria", "descricao": "Revisão, guarda e acompanhamento dos contratos e auditoria das entregas de pessoas e agentes."}, {"circulo": 9, "nome": "Dados, crises e relatos", "descricao": "Titulares de dados, comitê de crise, canal de relatos, comunicação às autoridades e relato de impacto."}]$j$::jsonb) as x(circulo smallint, nome text, descricao text);
